  if(t==='light'){
    return{dot:'rgba(120,110,200,.9)',line:'rgba(110,100,190,0.13)',orb1:'rgba(124,58,237,.20)',orb2:'rgba(79,70,229,.22)',bg1:'#ffffff',bg2:'#eef0f7'};
  }
  return{dot:'rgba(190,185,255,.85)',line:'rgba(150,145,255,0.12)',orb1:'rgba(124,58,237,.26)',orb2:'rgba(79,70,229,.30)',bg1:'#10101a',bg2:'#0c0c14'};
}

function draw(){
  time+=.016;
  var c=themeColors(readTheme());
  ctx.clearRect(0,0,W,H);

  var g1=ctx.createRadialGradient(W*.72,H*.18,0,W*.72,H*.18,W*.42);
  g1.addColorStop(0,c.orb1);g1.addColorStop(1,'transparent');
  ctx.fillStyle=g1;ctx.fillRect(0,0,W,H);
  var g2=ctx.createRadialGradient(W*.15,H*.82,0,W*.15,H*.82,W*.42);
  g2.addColorStop(0,c.orb2);g2.addColorStop(1,'transparent');
  ctx.fillStyle=g2;ctx.fillRect(0,0,W,H);

  var i,px,py,j,qx,qy;
  for(i=0;i<particles.length;i++){
    px=particles[i].x;py=particles[i].y;
    particles[i].x+=particles[i].vx;particles[i].y+=particles[i].vy;
    if(px<0||px>W)particles[i].vx*=-1;
    if(py<0||py>H)particles[i].vy*=-1;
    particles[i].x=Math.max(0,Math.min(W,particles[i].x));
    particles[i].y=Math.max(0,Math.min(H,particles[i].y));
  }
  for(i=0;i<particles.length;i++){
    px=particles[i].x;py=particles[i].y;
    for(j=i+1;j<particles.length;j++){
      qx=particles[j].x;qy=particles[j].y;
      var dx=px-qx,dy=py-qy,dist=Math.sqrt(dx*dx+dy*dy);
      if(dist<130){
        ctx.strokeStyle=c.line;
        ctx.lineWidth=1;
        ctx.beginPath();
        ctx.moveTo(px,py);ctx.lineTo(qx,qy);
        ctx.stroke();
      }
    }
  }
  for(i=0;i<particles.length;i++){
    px=particles[i].x;py=particles[i].y;
    ctx.fillStyle=c.dot;
    ctx.beginPath();
    ctx.arc(px,py,particles[i].r,0,Math.PI*2);
    ctx.fill();
  }
  rafId=requestAnimationFrame(draw);
}

/* ---------- Toggle ---------- */
function makeToggle(){
  var b=document.createElement('button');
  b.className='toggle';
  b.setAttribute('aria-label','Toggle light and dark theme');
  b.setAttribute('aria-pressed',readTheme()==='dark'?'false':'true');
  b.textContent=readTheme()==='dark'?'☀':'☾';
  b.addEventListener('click',function(){
    var n=readTheme()==='dark'?'light':'dark';
    try{localStorage.setItem(THEME_KEY,n)}catch(e){}
    applyTheme(n);
    b.textContent=n==='dark'?'☀':'☾';
    b.setAttribute('aria-pressed',n==='dark'?'false':'true');
  });
  return b;
}

